steps.solutionCode:
const rows = [
  '{ "name": "리액트 입문" }',
  '{ 잘못된 줄 }',
  '{ "name": "CSS 레이아웃" }',
];

function readNames() {
  const names = [];
  const skipped = [];

  for (const row of rows) {
    try {
      names.push(JSON.parse(row).name);
    } catch (e) {
      skipped.push(e.name);
    }
  }

  return { names, skipped };
}

function summarize(rows) {
  const ok = [];
  let failed = 0;

  for (const row of rows) {
    try {
      ok.push(JSON.parse(row).name);
    } catch (e) {
      failed += 1;
    }
  }

  return { ok, failed };
}
